ALTER POLICY prime99_notifications_read ON public.notifications USING(public.paid_alert_ready(auth.uid()) OR (auth.uid()=user_id AND EXISTS(SELECT 1 FROM public.free_work_notice_queue q WHERE q.notification_id=notifications.id AND q.user_id=auth.uid())));
REVOKE ALL ON FUNCTION public.free_work_notice_allowed(uuid) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.free_work_notice_allowed(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.notification_delivery_allowed(_user uuid,_notice uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT (auth.uid()=_user OR auth.role()='service_role') AND (public.paid_alert_ready(_user) OR EXISTS(SELECT 1 FROM public.free_work_notice_queue WHERE user_id=_user AND notification_id=_notice)); $$;